import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

// The storefront (port 5173) proxies /api and /media to the API, so requests
// are same-origin and the __Host- cookies work on http://localhost (D-132).
const api = process.env.API_URL ?? "http://127.0.0.1:4000";
// robots.txt and the sitemap are generated by the API (Phase 17); hosting
// maps the same two paths in production.
const seo = (path: string) => ({
  target: api,
  rewrite: () => `/api/v1/seo${path}`,
});
const proxy = {
  "/api": api,
  "/media": api,
  "/robots.txt": seo("/robots.txt"),
  "/sitemap.xml": seo("/sitemap.xml"),
};

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    strictPort: true,
    proxy,
  },
  preview: {
    port: 5173,
    strictPort: true,
    proxy,
  },
  build: { sourcemap: true },
});
